/** Every natural rank is independently exercised as a pair, triple and quad in both modes. */
export const NATURAL_COMBO_CASES: ClassificationCase[] = ([3, 4] as const).flatMap(players =>
  NATURAL_RANKS.flatMap((rank, strength) => ([2, 3, 4] as const).map(count => ({
    id: `RANK-${players}-${rank}-${count}`,
    description: `${players} players: ${count} cards of rank ${rank}`,
    players,
    cards: (['S', 'H', 'C', 'D'] as const).slice(0, count).map(suit => `${suit}-${rank}` as CardId),
    expected: { kind: (count === 2 ? 'PAIR' : count === 3 ? 'TRIPLE_BOMB' : 'FOUR_BOMB') as Kind, count, strength },
  }))),
);

/**
 * All legal sequence lengths AND starting ranks, generated from independent golden ranks.
 * Pair runs of 20/22 cards exercise the classifier's accepted shape, not a reachable deal:
 * a 3-player hand starts at 18 cards and a 4-player hand starts at 13 or 14 cards.
 */
export const SEQUENCE_CASES: ClassificationCase[] = [];
const sequenceRanks = ['4', '5', '6', '7', '8', '9', '10', 'J', 'Q', 'K', 'A'] as const;
for (const players of [3, 4] as const) {
  for (const kind of ['STRAIGHT', 'PAIR_RUN'] as const) {
    const minimum = kind === 'PAIR_RUN' ? 2 : players === 3 ? 4 : 3;
    for (let length = minimum; length <= 11; length++) {
      for (let start = 0; start + length <= 11; start++) {
        const ranks = sequenceRanks.slice(start, start + length);
        const cards = ranks.flatMap(rank => kind === 'PAIR_RUN'
          ? [`S-${rank}`, `H-${rank}`] as CardId[] : [`S-${rank}`] as CardId[]);
        SEQUENCE_CASES.push({
          id: `SEQ-${players}-${kind}-${length}-${start}`,
          description: `${players} players: ${kind} of ${length} ranks starting at ${ranks[0]}`,
          players, cards,
          expected: { kind, count: kind === 'PAIR_RUN' ? length * 2 : length, strength: start },
        });
      }
    }
  }
}
export const CLASSIFICATION_CASES = [...BASE_CLASSIFICATION_CASES, ...NATURAL_COMBO_CASES, ...SEQUENCE_CASES];

// Independently cover strict comparison in both directions and equality for every ordinary kind.
for (const [kind, count] of [['SINGLE', 1], ['PAIR', 2], ['STRAIGHT', 4], ['PAIR_RUN', 4]] as const) {
  for (const [strength, beats, label] of [[3, false, 'lower'], [4, false, 'equal'], [5, true, 'higher']] as const) {
    BEAT_CASES.push({ id: `ORDINARY-${kind}-${label}`, description: `${label} ${kind} of equal length`,
      candidate: [kind, count, strength], target: [kind, count, 4], beats });
  }
}
